"""Human-authored English and Georgian translations of source content."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
SOURCE=json.loads((ROOT/'source-content.json').read_text())
CATALOG={}
def clean(s):return '\n'.join(x.rstrip() for x in str(s).replace('\\r\\n','\n').splitlines()).strip()
def pair(ru,en,ka):CATALOG[clean(ru)]={'en':en,'ka':ka}
def put(path,en,ka):
 value=SOURCE
 for k in path.split('.'):value=value[int(k)] if isinstance(value,list) else value[k]
 pair(value,en,ka)

